// Generates the typed event models (AnglerEvent and AnglerData with its nested types) for all
// four SDKs from data-api's schema snapshot in spec/schema/. Never hand-edit the outputs; change
// the schema (re-export it) and run this again.
//
// Usage: node scripts/generate-models.mjs [--check]
//   --check  writes nothing; exits 1 if any generated file is out of date.
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { root, source, eventNames, objects, unions, unionsOf, T, cap, camel } from './lib/model.mjs';

const check = process.argv.includes('--check');

const header = (comment) =>
  `${comment} Generated by scripts/generate-models.mjs from data-api's events schema (${source.replace('exported from ', '')}).\n` +
  `${comment} Don't edit: re-export the schema and run the generator.\n`;
const doc = (indent, text, style) => {
  if (!text) return '';
  const clean = text.replace(/\s+/g, ' ').trim();
  return style === 'block' ? `${indent}/** ${clean} */\n` : `${indent}/// ${clean}\n`;
};

// ---------------------------------------------------------------------------------------------
// Swift

function swiftType(t) {
  switch (t.kind) {
    case 'string': return 'String';
    case 'number': return 'Double';
    case 'bool': return 'Bool';
    case 'array': return `[${swiftType(t.of)}]`;
    default: return T(t.name);
  }
}

function swift() {
  let out = header('//') + '\nimport Foundation\n\n';
  out += '/// A standard event name data-api accepts, or `.custom` for any other name.\n';
  out += 'public enum AnglerEvent: Hashable {\n';
  for (const n of eventNames) out += `    case ${camel(n)}\n`;
  out += '    /// Any other name; sent as `custom_event` with this `custom_event_name`.\n    case custom(String)\n\n';
  out += '    /// The name sent to data-api.\n    public var name: String {\n        switch self {\n';
  for (const n of eventNames) out += `        case .${camel(n)}: return "${n}"\n`;
  out += '        case .custom(let name): return name\n        }\n    }\n}\n';
  for (const o of objects) {
    out += '\n' + doc('', o.description);
    out += `public struct ${T(o.name)}: Encodable, Equatable {\n`;
    for (const f of o.fields) {
      out += doc('    ', f.description);
      out += `    public var ${f.json}: ${swiftType(f.type)}${f.required ? '' : '?'}\n`;
    }
    const params = o.fields.map((f) => `${f.json}: ${swiftType(f.type)}${f.required ? '' : '? = nil'}`);
    out += `\n    public init(${params.join(', ')}) {\n`;
    for (const f of o.fields) out += `        self.${f.json} = ${f.json}\n`;
    out += '    }\n}\n';
  }
  for (const u of unions) {
    out += `\n/// One of: ${u.members.map(T).join(', ')}.\npublic enum ${T(u.name)}: Encodable, Equatable {\n`;
    for (const m of u.members) out += `    case ${m[0].toLowerCase() + m.slice(1)}(${T(m)})\n`;
    out += '\n    public func encode(to encoder: Encoder) throws {\n        switch self {\n';
    for (const m of u.members) out += `        case .${m[0].toLowerCase() + m.slice(1)}(let value): try value.encode(to: encoder)\n`;
    out += '        }\n    }\n}\n';
  }
  return out;
}

// ---------------------------------------------------------------------------------------------
// Kotlin

function kotlinType(t) {
  switch (t.kind) {
    case 'string': return 'String';
    case 'number': return 'Number';
    case 'bool': return 'Boolean';
    case 'array': return `List<${kotlinType(t.of)}>`;
    default: return T(t.name);
  }
}

function kotlinToJson(t, v) {
  switch (t.kind) {
    case 'string': return `JsonValue.Str(${v})`;
    case 'bool': return `JsonValue.Bool(${v})`;
    case 'number': return `(JsonValue.from(${v}) ?: JsonValue.Null)`;
    case 'array': return `JsonValue.Arr(${v}.map { ${kotlinToJson(t.of, 'it')} })`;
    default: return `${v}.toJsonValue()`;
  }
}

function kotlin() {
  let out = header('//') + '\n@file:Suppress("RedundantVisibilityModifier")\n\npackage ai.getangler.analytics\n\n';
  out += 'import ai.getangler.analytics.payload.JsonValue\n\n';
  out += '/** A standard event name data-api accepts, or [Custom] for any other name. */\n';
  out += 'public sealed class AnglerEvent(public val name: String) {\n';
  for (const n of eventNames) out += `    public data object ${cap(camel(n))} : AnglerEvent("${n}")\n`;
  out += '\n    /** Any other name; sent as `custom_event` with this `custom_event_name`. */\n';
  out += '    public class Custom(name: String) : AnglerEvent(name) {\n';
  out += '        override fun equals(other: Any?): Boolean = other is Custom && other.name == name\n';
  out += '        override fun hashCode(): Int = name.hashCode()\n';
  out += '        override fun toString(): String = "Custom($name)"\n    }\n}\n';
  for (const u of unions) {
    out += `\n/** One of: ${u.members.map(T).join(', ')}. */\npublic sealed interface ${T(u.name)}\n`;
  }
  for (const o of objects) {
    out += '\n' + doc('', o.description, 'block');
    const supers = unionsOf.get(o.name)?.map(T) ?? [];
    out += `public data class ${T(o.name)} @JvmOverloads constructor(\n`;
    for (const f of o.fields) {
      out += doc('    ', f.description, 'block');
      out += `    val ${f.json}: ${kotlinType(f.type)}${f.required ? '' : '? = null'},\n`;
    }
    out += `)${supers.length ? ' : ' + supers.join(', ') : ''}\n`;
  }
  out += '\n// Conversion to the JSON the SDK sends. Null fields are left out.\n';
  for (const o of objects) {
    out += `\ninternal fun ${T(o.name)}.toJsonValue(): JsonValue = JsonValue.Obj(buildMap {\n`;
    for (const f of o.fields) {
      out += f.required
        ? `    put("${f.json}", ${kotlinToJson(f.type, f.json)})\n`
        : `    ${f.json}?.let { put("${f.json}", ${kotlinToJson(f.type, 'it')}) }\n`;
    }
    out += '})\n';
  }
  for (const u of unions) {
    out += `\ninternal fun ${T(u.name)}.toJsonValue(): JsonValue = when (this) {\n`;
    for (const m of u.members) out += `    is ${T(m)} -> toJsonValue()\n`;
    out += '}\n';
  }
  return out;
}

// ---------------------------------------------------------------------------------------------
// TypeScript

function tsType(t) {
  switch (t.kind) {
    case 'string': return 'string';
    case 'number': return 'number';
    case 'bool': return 'boolean';
    case 'array': return `${tsType(t.of)}[]`;
    default: return T(t.name);
  }
}

function typescript() {
  let out = header('//') + '\n';
  out += '/** The standard event names data-api accepts. Any other string is sent as a `custom_event`. */\n';
  out += 'export const AnglerEvent = {\n';
  for (const n of eventNames) out += `  ${camel(n)}: '${n}',\n`;
  out += '} as const;\n\n';
  out += 'export type AnglerStandardEvent = (typeof AnglerEvent)[keyof typeof AnglerEvent];\n';
  out += '/** A standard event name, or any other string for a custom event. */\n';
  out += '// eslint-disable-next-line @typescript-eslint/ban-types\n';
  out += 'export type AnglerEventName = AnglerStandardEvent | (string & {});\n';
  for (const u of unions) {
    out += `\n/** One of: ${u.members.map(T).join(', ')}. */\nexport type ${T(u.name)} = ${u.members.map(T).join(' | ')};\n`;
  }
  for (const o of objects) {
    out += '\n' + doc('', o.description, 'block') + `export interface ${T(o.name)} {\n`;
    for (const f of o.fields) {
      out += doc('  ', f.description, 'block');
      out += `  ${f.json}${f.required ? '' : '?'}: ${tsType(f.type)}${f.required ? '' : ' | null'};\n`;
    }
    out += '}\n';
  }
  return out;
}

// ---------------------------------------------------------------------------------------------
// Dart

function dartType(t) {
  switch (t.kind) {
    case 'string': return 'String';
    case 'number': return 'num';
    case 'bool': return 'bool';
    case 'array': return `List<${dartType(t.of)}>`;
    default: return T(t.name);
  }
}

function dartToJson(t, v) {
  switch (t.kind) {
    case 'string':
    case 'number':
    case 'bool':
      return v;
    case 'array': return `${v}.map((e) => ${dartToJson(t.of, 'e')}).toList()`;
    default: return `${v}.toJson()`;
  }
}

function dart() {
  let out = header('//') + '\n// ignore_for_file: lines_longer_than_80_chars\n\n';
  out += '/// A standard event name data-api accepts, or [AnglerEvent.custom] for any other name.\n';
  out += 'final class AnglerEvent {\n';
  out += '  const AnglerEvent._(this.name);\n\n';
  out += '  /// Any other name; sent as `custom_event` with this `custom_event_name`.\n';
  out += '  const AnglerEvent.custom(this.name);\n\n';
  out += '  /// The name sent to data-api.\n  final String name;\n\n';
  for (const n of eventNames) out += `  static const ${camel(n)} = AnglerEvent._('${n}');\n`;
  out += '\n  @override\n  bool operator ==(Object other) => other is AnglerEvent && other.name == name;\n\n';
  out += '  @override\n  int get hashCode => name.hashCode;\n\n';
  out += "  @override\n  String toString() => 'AnglerEvent($name)';\n}\n";
  for (const u of unions) {
    out += `\n/// One of: ${u.members.map(T).join(', ')}.\nsealed class ${T(u.name)} {\n  Map<String, Object?> toJson();\n}\n`;
  }
  for (const o of objects) {
    const supers = unionsOf.get(o.name)?.map(T) ?? [];
    out += '\n' + doc('', o.description) + `class ${T(o.name)}${supers.length ? ' implements ' + supers.join(', ') : ''} {\n`;
    out += `  const ${T(o.name)}({${o.fields.map((f) => `${f.required ? 'required ' : ''}this.${f.json}`).join(', ')}});\n`;
    for (const f of o.fields) {
      out += '\n' + doc('  ', f.description);
      out += `  final ${dartType(f.type)}${f.required ? '' : '?'} ${f.json};\n`;
    }
    out += `\n  /// The JSON sent to data-api. Null fields are left out.\n${supers.length ? '  @override\n' : ''}  Map<String, Object?> toJson() => {\n`;
    for (const f of o.fields) {
      out += f.required
        ? `        '${f.json}': ${dartToJson(f.type, f.json)},\n`
        : `        if (${f.json} != null) '${f.json}': ${dartToJson(f.type, `${f.json}!`)},\n`;
    }
    out += '      };\n}\n';
  }
  return out;
}

// ---------------------------------------------------------------------------------------------

const outputs = {
  'ios/Sources/AnglerAnalytics/Payload/Models.generated.swift': swift(),
  'android/angler-analytics/src/main/kotlin/ai/getangler/analytics/Models.generated.kt': kotlin(),
  'react-native/src/models.generated.ts': typescript(),
  'flutter/lib/src/models.generated.dart': dart(),
};

let stale = 0;
for (const [path, content] of Object.entries(outputs)) {
  const file = join(root, path);
  let current = null;
  try {
    current = readFileSync(file, 'utf8');
  } catch {}
  if (current === content) continue;
  if (check) {
    console.error(`generate-models: ${path} is out of date`);
    stale++;
  } else {
    writeFileSync(file, content);
    console.log(`generate-models: wrote ${path}`);
  }
}
if (check) {
  if (stale) {
    console.error('Run `node scripts/generate-models.mjs` and commit the result.');
    process.exit(1);
  }
  console.log(`generate-models: ${Object.keys(outputs).length} files up to date (${objects.length} types, ${unions.length} unions, ${eventNames.length} events)`);
}
